function Icon({ name, size = 20, className = '', ...props }) { return <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.65" strokeLinecap="round" strokeLinejoin="round" className={className} aria-hidden="true" {...props}><path d={paths[name] || paths.spark} /></svg>; }
function Avatar({ person, size = '', online = false }) { return <span className={`avatar ${person.color || 'sage'} ${size}`} aria-hidden="true">{person.initials || person.name?.slice(0, 2)}{online && <i />}</span>; }
function Badge({ children, tone = 'green', dot = false }) { return <span className={`badge ${tone}`}>{dot && <i />}{children}</span>; }
function Button({ children, icon, variant = 'primary', className = '', ...props }) { return <button className={`btn ${variant} ${className}`} {...props}>{icon && <Icon name={icon} size={17} />}{children}</button>; }
function AIFlag({ children = 'ИИ-помощник' }) { return <span className="ai-flag"><Icon name="spark" size={14} />{children}<span className="demo-dot" title="Демонстрационный сценарий" /></span>; }
const nav = [{ id: 'overview', name: 'Мой день', icon: 'home' }, { id: 'inbox', name: 'Переписки', icon: 'chat' }, { id: 'clients', name: 'Клиенты', icon: 'users' }, { id: 'academy', name: 'Академия', icon: 'book' }, { id: 'analytics', name: 'Разбор продаж', icon: 'chart' }, { id: 'knowledge', name: 'База знаний', icon: 'layers' }, { id: 'team', name: 'Команда', icon: 'medal' }, { id: 'integrations', name: 'Интеграции', icon: 'plug' }];
function Modal({ title, eyebrow, onClose, children, wide = false }) {
  const ref = useRef();
  useEffect(() => { const prev = document.activeElement; const key = e => { if (e.key === 'Escape') onClose(); if (e.key === 'Tab') { const els = [...ref.current.querySelectorAll('button, input, textarea, select, a[href]')].filter(x => !x.disabled); if (!els.length) return; if (e.shiftKey && document.activeElement === els[0]) { e.preventDefault(); els.at(-1).focus(); } else if (!e.shiftKey && document.activeElement === els.at(-1)) { e.preventDefault(); els[0].focus(); } } }; document.addEventListener('keydown', key); const bodyOverflow = document.body.style.overflow; document.body.style.overflow = 'hidden'; ref.current?.querySelector('input, textarea, button')?.focus(); return () => { document.removeEventListener('keydown', key); document.body.style.overflow = bodyOverflow; prev?.focus?.(); }; }, []);
  return <div className="modal-backdrop" onClick={e => e.target === e.currentTarget && onClose()}><section ref={ref} role="dialog" aria-modal="true" aria-labelledby="modal-title" className={`modal ${wide ? 'wide' : ''}`}><header>{eyebrow && <span className="eyebrow">{eyebrow}</span>}<h2 id="modal-title">{title}</h2><button className="icon-btn modal-close" aria-label="Закрыть окно" onClick={onClose}><Icon name="close" /></button></header>{children}</section></div>;
}
function PageTitle({ eyebrow, title, subtitle, children }) { return <div className="page-title"><div><span className="eyebrow">{eyebrow}</span><h1>{title}</h1><p>{subtitle}</p></div><div className="page-actions">{children}</div></div>; }
function Empty({ icon = 'search', title = 'Ничего не найдено', text = 'Попробуйте другой запрос или измените фильтры.' }) { return <div className="empty"><Icon name={icon} size={32} /><h3>{title}</h3><p>{text}</p></div>; }
function Sparkline({ color = '#54836a', variant = 0 }) { return <svg viewBox="0 0 150 45" className="sparkline" aria-hidden="true"><path d={variant ? 'M0 36 15 32 27 35 41 22 54 27 69 19 82 22 96 10 111 15 126 6 150 8' : 'M0 36 15 29 28 32 42 21 55 27 68 15 82 18 96 8 112 14 129 5 150 2'} stroke={color} strokeWidth="2.2" fill="none" /></svg>; }

function App() {
  const [data, setData] = useState(() => loadState(localStorage));
  const validPage = () => nav.some(x => x.id === location.hash.slice(1)) ? location.hash.slice(1) : 'overview';
  const [page, setPage] = useState(validPage);
  const [modal, setModal] = useState(null);
  const [toast, setToast] = useState('');
  const [selectedClient, setSelectedClient] = useState('alex');
  const [mobileNav, setMobileNav] = useState(false);
  const [storageWarning, setStorageWarning] = useState(false);
  useEffect(() => { try { localStorage.setItem(STORAGE_KEY, JSON.stringify(data)); } catch { setStorageWarning(true); } }, [data]);
  useEffect(() => { const listener = () => setPage(validPage()); window.addEventListener('hashchange', listener); return () => window.removeEventListener('hashchange', listener); }, []);
  useEffect(() => { if (!toast) return; const t = setTimeout(() => setToast(''), 4000); return () => clearTimeout(t); }, [toast]);
  useEffect(() => { document.title = `${nav.find(n => n.id === page)?.name} · Royal Reach`; }, [page]);
  function go(id) { location.hash = id; setPage(id); setMobileNav(false); window.scrollTo({ top: 0, behavior: 'instant' }); }
  function openChat(id) { setSelectedClient(id); go('inbox'); }
  function update(fn) { setData(prev => fn(prev)); }
  function notify(text) { setToast(text); }
  const unread = data.clients.filter(c => c.unread).length;
  const openTasks = data.tasks.filter(t => !t.done);
  function exportData() { const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' }); const url = URL.createObjectURL(blob); const a = document.createElement('a'); a.href = url; a.download = 'royal-reach-demo.json'; a.click(); setTimeout(() => URL.revokeObjectURL(url), 1000); notify('Демоданные экспортированы'); }
  const ctx = { data, update, go, openChat, setModal, notify, selectedClient, setSelectedClient };
  return <div className="app-shell">
    {mobileNav && <div className="nav-scrim" onClick={() => setMobileNav(false)} />}
    <aside className={`sidebar ${mobileNav ? 'open' : ''}`}>
      <button className="brand" onClick={() => go('overview')} aria-label="Royal Reach — на главную"><span className="brand-mark"><svg viewBox="0 0 36 36" fill="none"><path d="m6 10 7 6 5-10 5 10 7-6-4 17H10Z" fill="currentColor" /><path d="M11 31h14" stroke="currentColor" strokeWidth="2" /></svg></span><span>ROYAL REACH<small>SALES WORKSPACE</small></span></button>
      <div className="workspace-pill"><span className="workspace-icon">R</span><div><strong>Рабочее пространство</strong><small>Команда · 5 человек</small></div><Icon name="down" size={15} /></div>
      <span className="nav-label">РАБОТА И РАЗВИТИЕ</span>
      <nav aria-label="Основная навигация">{nav.map((n, i) => <React.Fragment key={n.id}>{i === 6 && <div className="nav-divider" />}<button className={`nav-link ${page === n.id ? 'active' : ''}`} aria-label={n.name} title={n.name} aria-current={page === n.id ? 'page' : undefined} onClick={() => go(n.id)}><Icon name={n.icon} size={19} /><span>{n.name}</span>{n.id === 'inbox' && unread > 0 && <b>{unread}</b>}{n.id === 'academy' && <span className="nav-new">NEW</span>}</button></React.Fragment>)}</nav>
      <div className="sidebar-bottom"><div className="sidebar-note"><span className="tiny-spark">✦</span><strong>Расти вместе с командой</strong><p>Один хороший разговор.<br />Один новый навык. Каждый день.</p><button onClick={() => go('academy')}>Перейти в академию <Icon name="arrow" size={15} /></button></div><button className="help-link" onClick={() => setModal({ type: 'about' })}><Icon name="help" size={18} />Как работает макет<Icon name="external" size={14} /></button><div className="profile"><Avatar person={team[0]} /><div><strong>Антон Ковалёв</strong><small>Менеджер по продажам</small></div><button className="icon-btn" aria-label="Настройки демо" onClick={() => setModal({ type: 'settings' })}><Icon name="settings" size={17} /></button></div></div>
    </aside>
    <div className="workspace-main"><header className="topbar"><div className="breadcrumb"><button className="icon-btn mobile-menu" aria-label="Открыть меню" onClick={() => setMobileNav(!mobileNav)}><Icon name="menu" /></button><span>Рабочее пространство</span><span className="slash">/</span><strong>{nav.find(n => n.id === page)?.name}</strong></div><div className="topbar-actions"><button className="global-search" onClick={() => setModal({ type: 'search' })}><Icon name="search" size={16} /><span>Найти что-нибудь</span><kbd>⌕</kbd></button><button className="demo-label" onClick={() => setModal({ type: 'about' })}><i />Интерактивное демо</button><button className="icon-btn notification" aria-label={`Уведомления: ${openTasks.length} задач`} onClick={() => setModal({ type: 'tasks' })}><Icon name="bell" /><i /></button><Avatar person={team[0]} size="small" /></div></header>
    <main className={`main-content ${page === 'inbox' ? 'inbox-page' : ''}`} key={page}>
      {storageWarning && <div role="status" className="storage-warning">Хранилище браузера недоступно. Изменения сохранятся только до закрытия страницы.</div>}
      {page === 'overview' && <Overview {...ctx} />}
      {page === 'inbox' && <Inbox {...ctx} />}
      {page === 'clients' && <Clients {...ctx} />}
      {page === 'academy' && <Academy {...ctx} />}
      {page === 'analytics' && <Analytics {...ctx} />}
      {page === 'knowledge' && <Knowledge {...ctx} />}
      {page === 'team' && <Team {...ctx} />}
      {page === 'integrations' && <Integrations {...ctx} />}
      {page !== 'inbox' && <footer className="page-footer"><span>ROYAL REACH <i /> Создаём сильную команду</span><button onClick={() => setModal({ type: 'about' })}>Демоданные · сохранение в этом браузере <Icon name="external" size={12} /></button></footer>}
    </main></div>
    {toast && <div role="status" className="toast"><span><Icon name="check" size={16} /></span>{toast}</div>}
    {modal && <AppModal modal={modal} onClose={() => setModal(null)} {...ctx} exportData={exportData} />}
  </div>;
}

function Overview({ data, update, go, openChat, setModal }) {
  const active = data.clients.filter(c => c.stage < 4);
  const todo = data.tasks.filter(t => !t.done);
  return <>
    <PageTitle eyebrow="СРЕДА, 28 ОКТЯБРЯ" title="Добрый день, Антон" subtitle="Всё, что помогает продавать лучше. И расти каждый день."><Button variant="secondary" icon="calendar" onClick={() => setModal({ type: 'tasks' })}>План на день</Button></PageTitle>
    <div className="dashboard-top"><section className="welcome-card"><div className="welcome-content"><span className="label-pill"><span className="sun-symbol">✳</span>Новый день — новые возможности</span><h2>Сильные продажи<br />начинаются с диалога.</h2><p>{data.clients.filter(c => c.unread).length ? `${data.clients.filter(c => c.unread).length} клиента ждут вашего внимания.` : 'На все новые вопросы ответили.'}<br />Помогите им сделать следующий шаг.</p><Button icon="chat" onClick={() => go('inbox')}>Открыть переписки <Icon name="arrow" size={16} /></Button></div><div className="growth-art" aria-hidden="true"><div className="orbit orbit-one" /><div className="orbit orbit-two" /><span className="art-star star-one">✳</span><span className="art-star star-two">✦</span><div className="art-card card-back"><span /><span /><span /></div><div className="art-card card-front"><span className="art-icon"><Icon name="growth" size={32} /></span><div className="art-bars">{[25, 38, 30, 55, 66, 82].map((v, i) => <i key={i} style={{ height: `${v}%` }} />)}</div><span className="art-card-line" /></div><div className="floating-tag"><Icon name="growth" size={17} /> Шаг за шагом вверх</div></div></section>
    <section className="daily-focus panel"><div className="section-top"><span className="eyebrow">ВАШ РИТМ</span><span className="fire-mini"><Icon name="fire" size={15} />{data.streak} дней</span></div><div className="focus-ring"><svg viewBox="0 0 110 110"><circle cx="55" cy="55" r="47" /><circle cx="55" cy="55" r="47" className="ring-value" style={{ strokeDashoffset: data.dailyDone ? 0 : 295 * .67 }} /></svg><div><strong>{data.dailyDone ? '✓' : '5'}<small>{data.dailyDone ? 'Готово' : `/ ${data.goal}`}</small></strong><span>{data.dailyDone ? 'занятие пройдено' : 'минут практики'}</span></div></div><h3>{data.dailyDone ? 'Отличный шаг вперёд' : 'Время для маленькой победы'}</h3><p>{data.dailyDone ? 'Завтра закрепим новый навык.' : 'Закрепите один навык за 15 минут.'}</p><button className="text-link" onClick={() => setModal({ type: 'lesson', moduleId: 1, daily: true })}>{data.dailyDone ? 'Повторить практику' : 'Продолжить занятие'}<Icon name="arrow" size={16} /></button></section></div>
    <div className="stats-grid"><Stat label="Клиентов в работе" value={active.length} note="Ваша активная воронка" icon="users" delta={`${active.length} сделок`} /><Stat label="Ждут ответа" value={data.clients.filter(c => c.unread).length} note="Вопросы, которые нельзя потерять" icon="chat" warn /><Stat label="Качество диалогов" value="87" suffix="/ 100" note="По учебным разборам" icon="spark" delta="+8 баллов" /></div>
    <div className="dashboard-bottom"><div className="main-column"><section className="panel task-panel"><div className="panel-heading"><div><span className="eyebrow">В ФОКУСЕ СЕГОДНЯ</span><h2>Обещания клиентам</h2></div><button className="text-link muted" onClick={() => setModal({ type: 'tasks' })}>Все задачи <Icon name="arrow" size={16} /></button></div><div className="task-list">{todo.length ? todo.slice(0, 3).map(t => { const c = data.clients.find(c => c.id === t.clientId); return <div className="task-row" key={t.id}><button className="task-check" aria-label={`Выполнить: ${t.title}`} onClick={() => update(d => ({ ...d, tasks: d.tasks.map(x => x.id === t.id ? { ...x, done: true } : x) }))}><Icon name="check" size={13} /></button><div><strong>{t.title}</strong><button onClick={() => openChat(c?.id)}>{c?.name || 'Без клиента'} <span>· {c?.company || 'Команда'}</span></button></div><span className="task-time"><Icon name="clock" size={13} />{t.time}</span><button className="icon-btn" aria-label={`Открыть задачу ${t.title}`} onClick={() => openChat(c?.id)}><Icon name="arrow" size={17} /></button></div>; }) : <Empty icon="check" title="Все обещания выполнены" text="Можно сосредоточиться на новых возможностях." />}</div></section>
    <section className="panel funnel-panel"><div className="panel-heading"><div><span className="eyebrow">ДВИЖЕНИЕ К РЕЗУЛЬТАТУ</span><h2>Пульс продаж</h2></div><Badge tone="gray">Демонстрационные сделки</Badge></div><div className="funnel-bars">{stages.map((s, i) => { const count = data.clients.filter(c => c.stage === i).length; return <button key={s} onClick={() => go('clients')}><div className="funnel-bar" style={{ height: `${38 + count * 23}px`, background: ['#e5ece7', '#cbdccf', '#a8c5af', '#709c7c', '#345e45'][i] }}><strong>{count}</strong></div><span>{s}</span></button>; })}</div></section></div>
    <div className="side-column"><section className="ai-insight"><AIFlag>Наблюдение дня</AIFlag><h3>Вопрос о цене —<br />начало разговора.</h3><p>Алексей спросил о составе пакета. Раскройте ценность предложения и уточните ожидаемый результат.</p><div className="insight-source"><Avatar person={data.clients[0]} size="tiny" /><span>Алексей · Город сегодня</span></div><button onClick={() => openChat('alex')}>Посмотреть контекст <Icon name="arrow" size={16} /></button><small>Учебный пример · вывод требует проверки</small></section>
    <section className="panel mini-team"><div className="panel-heading"><h2>Растём вместе</h2><button className="icon-btn" aria-label="Открыть команду" onClick={() => go('team')}><Icon name="arrow" size={17} /></button></div>{[team[1], team[2], team[0]].map((p, i) => <button className="mini-team-row" key={p.id} onClick={() => setModal({ type: 'person', person: p })}><span className="rank">{i + 1}</span><Avatar person={p} size="small" /><span>{p.name.split(' ')[0]}<small>{p.score} · качество диалогов</small></span><strong>{p.id === 1 ? data.xp : p.xp}<small>XP</small></strong></button>)}</section></div></div>
  </>;
}
function Stat({ label, value, suffix, note, icon, delta, warn }) { return <section className="stat-card panel"><div><span>{label}</span><span className={`stat-icon ${warn ? 'amber' : ''}`}><Icon name={icon} size={18} /></span></div><div className="stat-number"><strong>{value}</strong>{suffix && <span>{suffix}</span>}{delta && <Badge tone="soft">{delta}</Badge>}</div><div className="stat-note">{note}<Sparkline color={warn ? '#c6a277' : '#7a9c85'} variant={warn ? 1 : 0} /></div></section>; }

function Inbox({ data, update, selectedClient, setSelectedClient, setModal, notify }) {
  const [query, setQuery] = useState(''); const [filter, setFilter] = useState('Все'); const [draft, setDraft] = useState(''); const [tab, setTab] = useState('analysis'); const [busy, setBusy] = useState(false); const [analysed, setAnalysed] = useState(false); const messagesRef = useRef(null);
  const client = data.clients.find(c => c.id === selectedClient) || data.clients[0];
  useEffect(() => { setAnalysed(false); setDraft(''); update(d => ({ ...d, clients: d.clients.map(c => c.id === client.id && c.unread ? { ...c, unread: false } : c) })); }, [client.id]);
  useEffect(() => { if (messagesRef.current) messagesRef.current.scrollTop = messagesRef.current.scrollHeight; }, [client.id, client.messages.length]);
  const list = data.clients.filter(c => (filter === 'Все' || (filter === 'Непрочитанные' ? c.unread : c.channel === filter)) && (c.name + c.company).toLowerCase().includes(query.toLowerCase()));
  function select(c) { setSelectedClient(c.id); update(d => ({ ...d, clients: d.clients.map(x => x.id === c.id ? { ...x, unread: false } : x) })); }
  function send(e) { e.preventDefault(); if (!draft.trim()) return; const text = draft.trim(); const time = new Intl.DateTimeFormat('ru-RU', { hour: '2-digit', minute: '2-digit', timeZone: 'Europe/Moscow' }).format(new Date()); update(d => ({ ...d, clients: d.clients.map(c => c.id === client.id ? { ...c, unread: false, last: text, time, messages: [...c.messages, { from: 'me', text, time }] } : c) })); setDraft(''); notify('Ответ сохранён в демопереписке'); }
  function analyse() { setBusy(true); setTimeout(() => { setBusy(false); setAnalysed(true); }, 700); }
  return <><PageTitle eyebrow="ЕДИНОЕ ОКНО ОБЩЕНИЯ" title="Переписки" subtitle="Контекст, договорённости и следующий шаг — рядом с диалогом."><Badge tone="gray" dot>MAX и Telegram · демоданные</Badge></PageTitle>
  <div className="inbox-layout panel"><aside className="conversation-list"><div className="conversation-list-head"><strong>Входящие <span>{data.clients.length}</span></strong><Icon name="chat" size={18} /></div><label className="input-search"><Icon name="search" size={16} /><input aria-label="Поиск по перепискам" placeholder="Имя или компания" value={query} onChange={e => setQuery(e.target.value)} /></label><div className="mini-tabs">{['Все', 'MAX', 'Telegram', 'Непрочитанные'].map(f => <button key={f} className={filter === f ? 'active' : ''} onClick={() => setFilter(f)}>{f === 'Непрочитанные' ? 'Новые' : f}</button>)}</div><div className="conversations">{list.map(c => <button className={`conversation ${client.id === c.id ? 'selected' : ''}`} key={c.id} onClick={() => select(c)}><Avatar person={c} /><div><div><strong>{c.name.split(' ')[0]}</strong><time>{c.time}</time></div><span>{c.company}</span><p>{c.last}</p></div><span className={`channel-dot ${c.channel === 'MAX' ? 'max' : 'tg'}`}>{c.channel === 'MAX' ? 'M' : '↗'}</span>{c.unread && <i className="unread-dot" />}</button>)}{!list.length && <Empty />}</div><div className="list-foot"><Icon name="shield" size={13} />Вымышленные контакты для демонстрации</div></aside>
  <section className="chat-window"><header className="chat-head"><Avatar person={client} online /><div><h2>{client.name}</h2><span>{client.company} <i /> {client.channel}</span></div><button className="icon-btn" aria-label="Карточка клиента" onClick={() => setModal({ type: 'client', clientId: client.id })}><Icon name="external" size={18} /></button></header><div className="chat-stage"><span className="status-dot" />{stages[client.stage]}<span>{money(client.amount)}</span></div><button className="mobile-analysis" onClick={() => setModal({ type: 'review', clientId: client.id })}><Icon name="spark" size={14} />Разобрать диалог<span>Демо</span><Icon name="arrow" size={14} /></button><div className="chat-messages" ref={messagesRef}><div className="chat-date">28 октября · учебный диалог</div>{client.messages.map((m, i) => <div className={`message ${m.from}`} key={i}>{m.from === 'client' && <Avatar person={client} size="tiny" />}<div><p>{m.text}</p><time>{m.time}{m.from === 'me' && <Icon name="check" size={12} />}</time></div></div>)}<div className="chat-system"><Icon name="shield" size={13} />Сообщения сохраняются в макете и не отправляются клиентам</div></div><div className="composer-wrap"><button className="suggest-button" onClick={() => { setDraft(`${client.name.split(' ')[0]}, подскажите, какой результат вы хотите получить? Подберу два варианта под вашу задачу и подробно покажу состав каждого.`); notify('Учебный шаблон добавлен. Проверьте и отредактируйте ответ.'); }}><Icon name="spark" size={14} />Предложить ответ<span>Демо</span></button><form className="composer" onSubmit={send}><textarea aria-label="Сообщение клиенту" placeholder="Напишите ответ клиенту…" value={draft} onChange={e => setDraft(e.target.value)} onKeyDown={e => { if (e.key === 'Enter' && !e.shiftKey) send(e); }} rows={2} maxLength={4000} /><div><span>Enter — сохранить · Shift + Enter — новая строка</span><button className="send-button" aria-label="Сохранить сообщение" disabled={!draft.trim()}><Icon name="send" size={18} /></button></div></form></div></section>
  <aside className="context-panel"><div className="context-tabs">{[['analysis', 'ИИ-разбор'], ['profile', 'Клиент']].map(([id, label]) => <button key={id} className={tab === id ? 'active' : ''} onClick={() => setTab(id)}>{label}</button>)}</div>{tab === 'analysis' ? <><div className="context-intro"><span className="ai-icon"><Icon name="spark" size={22} /></span><AIFlag>Второй взгляд на диалог</AIFlag><h3>Больше контекста.<br />Точнее следующий шаг.</h3><p>Помощник находит вопросы клиента и предлагает, на что обратить внимание.</p></div><Button variant="secondary" icon={busy ? 'refresh' : 'spark'} className="full" disabled={busy} onClick={analyse}>{busy ? 'Разбираем учебный пример…' : analysed ? 'Повторить разбор' : 'Разобрать диалог'}</Button>{analysed ? <div className="analysis-result"><Badge tone="green">Учебный разбор готов</Badge><h4>Что видно из переписки</h4><p>Клиент обозначил задачу: «{client.need}». Важно связать предложение с ожидаемым результатом.</p><div className="quote-box">{client.messages.filter(m => m.from === 'client').at(-1)?.text}</div><h4>Что сделать дальше</h4><ul><li>Ответить на конкретный вопрос.</li><li>Уточнить критерий успешного результата.</li><li>Согласовать следующий шаг и срок.</li></ul><Button icon="book" onClick={() => setModal({ type: 'review', clientId: client.id })}>Создать учебный пример</Button><small>Готовый демосценарий. Настоящий ИИ не подключён.</small></div> : <><div className="context-card"><span className="eyebrow">ФОКУС РАЗГОВОРА</span><strong>{client.need}</strong><p>Источник: учебная карточка клиента</p></div><div className="context-tip"><Icon name="target" size={18} /><p>Хороший следующий шаг отвечает на вопрос: кто, что и к какому времени сделает?</p></div></>}</> : <div className="client-context"><Avatar person={client} size="large" /><h3>{client.name}</h3><p>{client.company}</p><dl><dt>Интерес</dt><dd>{client.interest}</dd><dt>Задача</dt><dd>{client.need}</dd><dt>Ответственный</dt><dd>{team.find(p => p.id === client.owner)?.name}</dd><dt>Источник</dt><dd>Демонстрационная карточка</dd></dl><Button variant="secondary" icon="plus" onClick={() => setModal({ type: 'task', clientId: client.id })}>Добавить задачу</Button></div>}</aside></div></>;
}

function Clients({ data, setModal, openChat }) {
  const [query, setQuery] = useState(''); const [filter, setFilter] = useState('all'); const [view, setView] = useState('table');
  const list = data.clients.filter(c => (filter === 'all' || c.stage === Number(filter)) && (c.name + c.company).toLowerCase().includes(query.toLowerCase()));
  return <><PageTitle eyebrow="ОТ ПЕРВОГО КОНТАКТА ДО ПАРТНЁРСТВА" title="Клиенты" subtitle="За каждой сделкой — человек и его задача."><Button icon="plus" onClick={() => setModal({ type: 'newClient' })}>Добавить клиента</Button></PageTitle><div className="client-summary"><div><span>В работе</span><strong>{data.clients.filter(c => c.stage < 4).length}<small> клиентов</small></strong></div><div><span>Объём активных предложений</span><strong>{money(data.clients.filter(c => c.stage < 4).reduce((s, c) => s + c.amount, 0))}</strong></div><div><span>Оплаченные сделки</span><strong>{money(data.clients.filter(c => c.stage === 4).reduce((s, c) => s + c.amount, 0))}</strong></div></div><section className="panel"><div className="table-toolbar"><label className="input-search"><Icon name="search" size={17} /><input value={query} onChange={e => setQuery(e.target.value)} aria-label="Поиск клиентов" placeholder="Найти клиента или компанию" /></label><select aria-label="Фильтр по этапу сделки" value={filter} onChange={e => setFilter(e.target.value)}><option value="all">Все этапы</option>{stages.map((s, i) => <option key={s} value={i}>{s}</option>)}</select><div className="view-toggle"><button className={view === 'table' ? 'active' : ''} aria-label="Таблица" onClick={() => setView('table')}><Icon name="menu" size={17} /></button><button className={view === 'cards' ? 'active' : ''} aria-label="Карточки" onClick={() => setView('cards')}><Icon name="layers" size={17} /></button></div></div>{view === 'table' ? <div className="table-scroll"><table className="client-table"><thead><tr><th>Клиент / компания</th><th>Этап</th><th>Канал</th><th>Сумма</th><th>Ответственный</th><th /></tr></thead><tbody>{list.map(c => <tr key={c.id}><td><button className="table-person" onClick={() => setModal({ type: 'client', clientId: c.id })}><Avatar person={c} /><span><strong>{c.name}</strong><small>{c.company}</small></span></button></td><td><Badge tone={c.stage === 4 ? 'green' : c.stage === 3 ? 'purple' : 'gray'}>{stages[c.stage]}</Badge></td><td><span className="channel-label"><i className={c.channel === 'MAX' ? 'max' : 'tg'} />{c.channel}</span></td><td className="money-cell">{money(c.amount)}</td><td><span className="owner-name">{team.find(p => p.id === c.owner)?.name.split(' ')[0]}</span></td><td><button className="icon-btn" aria-label={`Открыть переписку: ${c.name}`} onClick={() => openChat(c.id)}><Icon name="arrow" size={17} /></button></td></tr>)}</tbody></table></div> : <div className="client-card-grid">{list.map(c => <button className="client-card" key={c.id} onClick={() => setModal({ type: 'client', clientId: c.id })}><div><Avatar person={c} /><Badge tone="gray">{c.channel}</Badge></div><h3>{c.name}</h3><p>{c.company}</p><span>{c.need}</span><footer><Badge tone={c.stage === 4 ? 'green' : 'gray'}>{stages[c.stage]}</Badge><strong>{money(c.amount)}</strong></footer></button>)}</div>}{!list.length && <Empty />}<div className="table-foot">{list.length} из {data.clients.length} клиентов<span>Все контакты вымышлены</span></div></section></>;
}

function Academy({ data, update, setModal }) {
  const [tab, setTab] = useState('route'); const [duration, setDuration] = useState(data.goal);
  const current = modules.find(m => !data.completed.includes(m.id));
  return <><PageTitle eyebrow="ROYAL REACH ACADEMY" title="Навык приходит с практикой" subtitle="Учитесь на реальных ситуациях. Закрепляйте маленькими шагами."><div className="academy-counters"><span><Icon name="fire" size={18} />{data.streak} дней подряд</span><span className="xp-pill">✦ {data.xp} XP</span></div></PageTitle><div className="section-tabs" role="tablist" aria-label="Разделы академии">{[['route', 'Мой маршрут'], ['daily', 'Ежедневная практика'], ['cases', 'Из переписок']].map(([id, t]) => <button role="tab" aria-selected={tab === id} key={id} className={tab === id ? 'active' : ''} onClick={() => setTab(id)}>{t}{id === 'cases' && <span>{data.reviews.length}</span>}</button>)}</div>
  {tab === 'route' && <><section className="academy-hero"><div><span className="eyebrow">ВАША СЛЕДУЮЩАЯ СТУПЕНЬ</span><h2>{current ? ["Покажите ценность.\nПомогите выбрать.", "Лучший ответ начинается\nс хорошего вопроса.", "За каждым сомнением\nесть важный вопрос.", "Согласуйте шаг.\nПродолжите диалог."][current.id] : 'Основы пройдены.\nПродолжаем расти.'}</h2><p>{current ? `Блок ${current.id + 1} · ${current.title}. ${current.desc}.` : 'Все четыре блока пройдены. Применяйте навыки в ежедневной практике.'}</p><Button onClick={() => setModal({ type: 'lesson', moduleId: current?.id ?? 1, daily: !current })}>Продолжить обучение <Icon name="arrow" size={17} /></Button><span className="hero-time"><Icon name="clock" size={14} />Один урок · около 7 минут</span></div><div className="steps-art" aria-hidden="true"><span className="step-spark">✳</span>{[0, 1, 2, 3].map((v) => <div key={v} className={`step-block step-${v}`}><Icon name={data.completed.includes(v) ? 'check' : v === current?.id ? 'growth' : 'lock'} size={v === current?.id ? 32 : 21} /><small>0{v + 1}</small></div>)}<span className="steps-line" /></div></section><div className="academy-layout"><section className="learning-path"><div className="panel-heading"><h2>Четыре блока. Одна сильная база.</h2><span className="muted">{data.completed.length} из 4 пройдено</span></div>{modules.map((m, i) => { const done = data.completed.includes(i); const locked = i > 0 && !data.completed.includes(i - 1); return <button className={`module-card ${done ? 'completed' : locked ? 'locked' : 'current'}`} key={m.id} onClick={() => !locked && setModal({ type: 'lesson', moduleId: m.id })} disabled={locked}><span className="module-track"><span>{done ? <Icon name="check" size={18} /> : locked ? <Icon name="lock" size={16} /> : `0${i + 1}`}</span></span><span className="module-content"><span className="eyebrow">БЛОК 0{i + 1} <i /> {m.tag}</span><strong>{m.title}</strong><span>{m.desc}</span><small><Icon name="book" size={13} />{m.lessons} шага <i /> {m.duration}</small></span><span className="module-tail">{done ? <Badge tone="green">Пройден</Badge> : locked ? <span className="lock-note">После блока {i}</span> : <span className="module-next"><Icon name="arrow" size={20} /></span>}</span></button>; })}</section><aside className="academy-side"><section className="panel habit-card"><div className="panel-heading"><h3>Ритм важнее рывка</h3><span className="fire-mini"><Icon name="fire" size={17} />{data.streak}</span></div><div className="week-days">{['Пн', 'Вт', 'Ср', 'Чт', 'Пт', 'Сб', 'Вс'].map((d, i) => <div key={d}><span>{d}</span><i className={i < 2 || (i === 2 && data.dailyDone) ? 'done' : i === 2 ? 'today' : ''}>{i < 2 || (i === 2 && data.dailyDone) ? <Icon name="check" size={14} /> : i === 2 ? '28' : [26, 27, 28, 29, 30, 31, 1][i]}</i></div>)}</div><p>Один небольшой шаг каждый день превращается в большой навык.</p></section><section className="panel skill-card"><span className="icon-tile"><Icon name="medal" size={25} /></span><h3>Ваш следующий уровень</h3><p>«Мастер диалога»</p><div className="progress-track"><span style={{ width: `${Math.min(data.xp / 16, 100)}%` }} /></div><small>{data.xp} / 1 600 XP</small><div className="skill-note"><Icon name="spark" size={15} />Баллы за полезные действия и освоенные навыки</div></section><div className="quiet-note"><Icon name="shield" size={17} /><p>ИИ помогает разобрать ответ. Спорные оценки проверяет наставник.</p></div></aside></div></>}
  {tab === 'daily' && <section className="daily-practice panel"><div className="daily-illustration"><Icon name="growth" size={70} /><span>МАЛЕНЬКИЕ ШАГИ → БОЛЬШОЙ РОСТ</span></div><div><AIFlag>Персональная практика</AIFlag><h2>Сегодня: понять, что стоит за «дорого»</h2><p>Уточняющий вопрос, небольшой кейс и диалог с учебным клиентом. Повторяем сложные темы через 1, 3 и 7 дней.</p><div className="duration-picker" aria-label="Продолжительность занятия">{[15, 20, 30].map(n => <button key={n} className={duration === n ? 'active' : ''} onClick={() => { setDuration(n); update(d => ({ ...d, goal: n })); }}><Icon name="clock" size={16} />{n} минут</button>)}</div><Button icon="arrow" onClick={() => setModal({ type: 'lesson', moduleId: 1, daily: true })}>{data.dailyDone ? 'Повторить занятие' : 'Начать практику'}</Button><p className="small-note">В макете доступен один полный учебный сценарий.</p></div></section>}
  {tab === 'cases' && <><div className="section-explainer"><AIFlag>Из работы — в обучение</AIFlag><h2>Каждый диалог может стать полезным уроком</h2><p>Выберите переписку, проверьте вывод и утвердите пример для команды.</p></div><div className="case-grid">{data.clients.slice(0, 4).map(c => <section className="panel case-card" key={c.id}><div><Avatar person={c} /><span><strong>{c.name}</strong><small>{c.company} · {c.channel}</small></span></div><blockquote>«{c.messages.filter(m => m.from === 'client').at(-1)?.text}»</blockquote><Button variant="secondary" icon="spark" onClick={() => setModal({ type: 'review', clientId: c.id })}>Разобрать пример</Button></section>)}</div>{data.reviews.length > 0 && <div className="approved-strip"><Icon name="check" size={19} />Утверждено учебных примеров: {data.reviews.length}. Они доступны в базе знаний.</div>}</>}
  </>;
}

function Analytics({ data, setModal, openChat }) {
  const [period, setPeriod] = useState('week');
  const categories = ['Понимание задачи', 'Ответ на вопрос', 'Работа с возражением', 'Следующий шаг'];
  return <><PageTitle eyebrow="КАЧЕСТВО, КОТОРОЕ МОЖНО ОБЪЯСНИТЬ" title="Разбор продаж" subtitle="Замечаем сильные действия. Находим конкретные точки роста."><div className="segmented">{[['week', 'Неделя'], ['month', 'Месяц']].map(([id, s]) => <button className={period === id ? 'active' : ''} key={id} onClick={() => setPeriod(id)}>{s}</button>)}</div></PageTitle><div className="analytics-top"><section className="panel chart-card"><div className="panel-heading"><div><span className="eyebrow">КАЧЕСТВО ДИАЛОГОВ</span><h2>Рост, который видно</h2></div><Badge tone="green">+{period === 'week' ? '8' : '16'} баллов</Badge></div><div className="chart-legend"><strong>{period === 'week' ? '87' : '84'}<small>/ 100</small></strong><span><i />Учебные оценки · {period === 'week' ? 'последние 7 дней' : 'последние 4 недели'}</span></div><div className="line-chart"><div className="chart-grid"><span>100</span><span>80</span><span>60</span></div><svg viewBox="0 0 600 160" preserveAspectRatio="none" role="img" aria-label="Демонстрационная динамика качества: рост с 76 до 87 баллов"><defs><linearGradient id="chart-fill" x1="0" y1="0" x2="0" y2="1"><stop stopColor="#96b7a1" stopOpacity=".28" /><stop offset="1" stopColor="#96b7a1" stopOpacity="0" /></linearGradient></defs><path d={period === 'week' ? 'M0 128C50 128 50 100 100 105S150 130 200 100 250 76 300 80 350 50 400 57 450 73 500 42 550 35 600 18V160H0Z' : 'M0 145C75 145 100 115 150 120S220 92 300 86 380 95 450 54 550 63 600 30V160H0Z'} fill="url(#chart-fill)" /><path d={period === 'week' ? 'M0 128C50 128 50 100 100 105S150 130 200 100 250 76 300 80 350 50 400 57 450 73 500 42 550 35 600 18' : 'M0 145C75 145 100 115 150 120S220 92 300 86 380 95 450 54 550 63 600 30'} fill="none" stroke="#467559" strokeWidth="3" /></svg><div className="chart-labels">{(period === 'week' ? ['Чт', 'Пт', 'Сб', 'Вс', 'Пн', 'Вт', 'Ср'] : ['1 неделя', '2 неделя', '3 неделя', '4 неделя']).map(d => <span key={d}>{d}</span>)}</div></div></section><section className="panel competency-card"><div className="panel-heading"><h2>Из чего складывается оценка</h2></div>{categories.map((s, i) => <div className="competency" key={s}><div><span>{s}</span><strong>{[91, 88, 76, 87][i]}</strong></div><div className="progress-track"><span style={{ width: `${[91, 88, 76, 87][i]}%`, background: i === 2 ? '#c7a675' : undefined }} /></div></div>)}<p><Icon name="shield" size={15} />Оцениваем действия в диалоге. Отказ клиента сам по себе не снижает балл.</p></section></div><section className="panel review-table"><div className="panel-heading"><div><span className="eyebrow">СНАЧАЛА ФАКТЫ, ЗАТЕМ ВЫВОДЫ</span><h2>Ситуации для разбора</h2></div><Badge tone="gray">{data.reviews.length} проверено наставником</Badge></div>{data.clients.slice(0, 3).map((c, i) => <div className="review-row" key={c.id}><span className={`review-indicator ${i === 0 ? 'amber' : i === 1 ? 'green' : 'blue'}`}><Icon name={i === 0 ? 'target' : i === 1 ? 'check' : 'chat'} size={20} /></span><div><strong>{['Раскрыть состав предложения', 'Закрепить хороший уточняющий вопрос', 'Согласовать критерий результата'][i]}</strong><span>{c.name} · {c.company}</span></div><Badge tone={i === 1 ? 'green' : 'sand'}>{i === 1 ? 'Сильный пример' : 'Точка роста'}</Badge><button className="text-link" onClick={() => setModal({ type: 'review', clientId: c.id })}>Проверить <Icon name="arrow" size={16} /></button><button className="icon-btn" aria-label={`Открыть диалог с ${c.name}`} onClick={() => openChat(c.id)}><Icon name="external" size={16} /></button></div>)}</section><div className="analytics-bottom"><div className="methodology-note"><AIFlag>Принцип работы</AIFlag><h3>У каждой оценки есть основание.</h3><p>Цитата из переписки → наблюдаемое действие → критерий → рекомендация. Наставник может исправить вывод до того, как он попадёт в обучение.</p></div><Button variant="secondary" icon="download" onClick={() => setModal({ type: 'report' })}>Посмотреть отчёт по сотруднику</Button></div></>;
}

function Knowledge({ data, setModal }) {
  const [query, setQuery] = useState(''); const [category, setCategory] = useState('Все материалы');
  const cats = ['Все материалы', 'Продукт', 'Методология', 'Возражения', 'Коммуникация', 'Из переписок'];
  const list = data.knowledge.filter(k => k.approved && (category === 'Все материалы' || k.category === category) && (k.title + k.body).toLowerCase().includes(query.toLowerCase()));
  return <><PageTitle eyebrow="ОБЩИЙ ОПЫТ КОМАНДЫ" title="Знания, которые работают" subtitle="Продукт, стандарты и проверенные выводы из диалогов."><Button variant="secondary" icon="plus" onClick={() => setModal({ type: 'newKnowledge' })}>Добавить материал</Button></PageTitle><section className="knowledge-hero"><span className="knowledge-orbit" aria-hidden="true"><Icon name="layers" size={45} /></span><div><AIFlag>Ответ с опорой на источник</AIFlag><h2>Нужное знание. В нужный момент.</h2><p>Находим подходящий фрагмент в утверждённых материалах и показываем, откуда он взят.</p></div><Button onClick={() => setModal({ type: 'ask' })} icon="search">Спросить базу знаний</Button></section><div className="knowledge-toolbar"><label className="input-search"><Icon name="search" size={17} /><input aria-label="Поиск материалов" placeholder="Название или фраза из материала" value={query} onChange={e => setQuery(e.target.value)} /></label><span className="muted">{list.length} материалов</span></div><div className="filter-pills">{cats.map(c => <button className={category === c ? 'active' : ''} key={c} onClick={() => setCategory(c)}>{c}</button>)}</div><div className="knowledge-grid">{list.map(k => <button className="knowledge-card panel" key={k.id} onClick={() => setModal({ type: 'article', article: k })}><div><span className={`icon-tile ${k.category === 'Возражения' ? 'peach' : k.category === 'Продукт' ? 'blue' : ''}`}><Icon name={k.icon} size={23} /></span><Icon name="arrow" size={18} /></div><Badge tone="gray">{k.category}</Badge><h3>{k.title}</h3><p>{k.body}</p><footer><span><Icon name="shield" size={13} />Утверждено</span><span>{k.updated}</span></footer></button>)}</div>{!list.length && <Empty />}<div className="knowledge-footnote"><Icon name="shield" size={18} /><p>В обучение попадают только утверждённые материалы. В макете поиск работает локально по словам; генерация ИИ появится после подключения API.</p></div></>;
}

function Team({ data, setModal }) { const [sort, setSort] = useState('quality'); const people = [...team].sort((a, b) => sort === 'quality' ? b.score - a.score : (b.id === 1 ? data.xp : b.xp) - (a.id === 1 ? data.xp : a.xp)); return <><PageTitle eyebrow="СИЛЬНЕЕ ВМЕСТЕ" title="Команда и развитие" subtitle="Видим прогресс каждого. Помогаем там, где это действительно нужно."><Badge tone="gray">5 участников · демокоманда</Badge></PageTitle><section className="team-banner"><div><span className="eyebrow">ОБЩИЙ ПРОГРЕСС</span><h2>Сильная команда —<br />это привычка учиться.</h2><p>Сравниваем действия и развитие навыков.<br />Подтверждаем выводы примерами из работы.</p></div><div className="team-stack">{team.map(p => <Avatar key={p.id} person={p} size="large" />)}<span>5 разных людей.<br /><strong>Одна общая цель.</strong></span></div></section><div className="team-toolbar"><h2>Личный прогресс</h2><div className="segmented"><button className={sort === 'quality' ? 'active' : ''} onClick={() => setSort('quality')}>По качеству</button><button className={sort === 'xp' ? 'active' : ''} onClick={() => setSort('xp')}>По баллам</button></div></div><div className="team-grid">{people.map((p, i) => <button key={p.id} className="person-card panel" onClick={() => setModal({ type: 'person', person: p })}><div className="person-card-top"><Avatar person={p} size="large" /><span className={`person-rank ${i === 0 ? 'first' : ''}`}>{i === 0 ? <Icon name="medal" size={19} /> : `0${i + 1}`}</span></div><h3>{p.name}{p.id === 1 && <small>Вы</small>}</h3><p>{p.role}</p><div className="person-numbers"><div><strong>{p.score}<small>/100</small></strong><span>Качество</span></div><div><strong>{p.id === 1 ? data.xp : p.xp}<small>XP</small></strong><span>Практика</span></div></div><div className="person-growth"><span>Обучение</span><strong>{p.id === 1 ? data.completed.length : p.id === 5 ? 1 : 3} / 4 блока</strong></div><div className="progress-track"><span style={{ width: `${(p.id === 1 ? data.completed.length : p.id === 5 ? 1 : 3) * 25}%` }} /></div><footer>Посмотреть навыки <Icon name="arrow" size={17} /></footer></button>)}</div><div className="quiet-note team-note"><Icon name="shield" size={20} /><p>Сводка описывает наблюдаемые навыки и ответы. Решения о роли сотрудника принимает руководитель после личной проверки.</p></div></>; }

function Integrations({ setModal }) {
  return <><PageTitle eyebrow="СВЯЗАННОЕ РАБОЧЕЕ ПРОСТРАНСТВО" title="Всё на своих местах" subtitle="Переписки, знания и ИИ — в одном понятном процессе."><Badge tone="sand">План подключения</Badge></PageTitle><div className="integration-notice"><Icon name="plug" size={20} /><div><strong>Здесь показана архитектура будущей системы</strong><p>Внешние сервисы не подключены. Все данные и действия в макете остаются в браузере.</p></div></div><div className="integration-grid">{[{ id: 'telegram', name: 'Telegram', symbol: '↗', color: 'telegram', desc: 'Переписки команды в едином окне', detail: '4 тестовых аккаунта', tag: 'Мессенджер' }, { id: 'max', name: 'MAX', symbol: 'M', color: 'max', desc: 'Контекст клиентских разговоров', detail: '4 тестовых аккаунта', tag: 'Мессенджер' }, { id: 'gpt', name: 'OpenAI GPT', symbol: '✺', color: 'gpt', desc: 'Разборы, практика и обратная связь', detail: 'Модели для разных задач', tag: 'Интеллект' }, { id: 'supabase', name: 'Supabase', symbol: 'ϟ', color: 'supabase', desc: 'История, знания и прогресс команды', detail: 'Общее хранилище и поиск', tag: 'Данные' }].map(p => <section className="integration-card panel" key={p.id}><div><span className={`service-logo ${p.color}`}>{p.symbol}</span><Badge tone="gray">{p.tag}</Badge></div><h2>{p.name}</h2><p>{p.desc}</p><div className="integration-detail"><Icon name={p.id === 'supabase' ? 'layers' : p.id === 'gpt' ? 'spark' : 'users'} size={16} />{p.detail}</div><footer><span><i />Не подключено</span><button className="text-link" onClick={() => setModal({ type: 'integration', id: p.id })}>Подробнее <Icon name="arrow" size={16} /></button></footer></section>)}</div><section className="panel architecture"><div className="panel-heading"><div><span className="eyebrow">КАК ДВИЖЕТСЯ ИНФОРМАЦИЯ</span><h2>Больше памяти. Меньше лишнего контекста.</h2></div><AIFlag>Будущая интеграция</AIFlag></div><div className="architecture-flow">{[{ icon: 'chat', title: 'Переписки', text: 'Сообщения и договорённости' }, { icon: 'layers', title: 'База знаний', text: 'История и утверждённые материалы' }, { icon: 'search', title: 'Отбор контекста', text: 'Только нужные фрагменты' }, { icon: 'spark', title: 'GPT', text: 'Ответ с указанием источников' }].map((s, i) => <React.Fragment key={s.title}><div className="architecture-step"><span><Icon name={s.icon} size={22} /></span><h3>{s.title}</h3><p>{s.text}</p></div>{i < 3 && <Icon name="arrow" className="flow-arrow" size={20} />}</React.Fragment>)}</div><p className="architecture-caption">В GPT передаётся выбранный контекст, а не вся история базы. Экономия токенов зависит от настройки поиска и проверяется на реальной нагрузке.</p></section></>;
}

function AppModal({ modal, onClose, data, update, setModal, notify, go, openChat, exportData }) {
  const c = data.clients.find(c => c.id === modal.clientId);
  if (modal.type === 'lesson') return <Lesson modal={modal} onClose={onClose} data={data} update={update} notify={notify} />;
  if (modal.type === 'review') return <Review client={c} onClose={onClose} data={data} update={update} notify={notify} go={go} />;
  if (modal.type === 'search') return <GlobalSearch data={data} onClose={onClose} openChat={openChat} setModal={setModal} go={go} />;
  if (modal.type === 'ask') return <AskKnowledge data={data} onClose={onClose} setModal={setModal} />;
  if (modal.type === 'newClient') return <NewClient onClose={onClose} update={update} notify={notify} />;
  if (modal.type === 'newKnowledge') return <NewKnowledge onClose={onClose} update={update} notify={notify} />;
  if (modal.type === 'task') return <NewTask client={c} onClose={onClose} update={update} notify={notify} />;
  if (modal.type === 'client') return <Modal title={c.name} eyebrow="КАРТОЧКА КЛИЕНТА" onClose={onClose}><div className="modal-person"><Avatar person={c} size="large" /><div><h3>{c.company}</h3><span>{c.channel} · {money(c.amount)}</span></div></div><dl className="detail-list"><dt>Задача клиента</dt><dd>{c.need}</dd><dt>Интерес</dt><dd>{c.interest}</dd><dt>Ответственный</dt><dd>{team.find(p => p.id === c.owner)?.name}</dd></dl><label className="form-label">Этап сделки<select value={c.stage} onChange={e => update(d => ({ ...d, clients: d.clients.map(x => x.id === c.id ? { ...x, stage: Number(e.target.value) } : x) }))}>{stages.map((s, i) => <option value={i} key={s}>{s}</option>)}</select></label><div className="modal-actions"><Button variant="secondary" icon="plus" onClick={() => setModal({ type: 'task', clientId: c.id })}>Задача</Button><Button icon="chat" onClick={() => { onClose(); openChat(c.id); }}>Открыть переписку</Button></div><p className="small-note">Учебный контакт. Изменения сохраняются только в этом браузере.</p></Modal>;
  if (modal.type === 'article') return <Modal title={modal.article.title} eyebrow={modal.article.category.toUpperCase()} onClose={onClose}><div className="article-meta"><Badge tone="green"><Icon name="shield" size={12} />Утверждено</Badge><span>{modal.article.updated}</span></div><div className="article-body">{modal.article.body.split('\n').map((p, i) => <p key={i}>{p}</p>)}</div><div className="source-box"><Icon name="file" size={19} /><div><small>Источник</small><strong>{modal.article.source}</strong></div></div><div className="modal-actions"><Button icon="book" onClick={() => setModal({ type: 'lesson', moduleId: 1, daily: true })}>Закрепить на практике</Button></div></Modal>;
  if (modal.type === 'tasks') return <Modal title="План на день" eyebrow="ОБЕЩАНИЯ ПОД КОНТРОЛЕМ" onClose={onClose}><div className="modal-task-list">{data.tasks.map(t => <div key={t.id} className={`task-row ${t.done ? 'done' : ''}`}><button className={`task-check ${t.done ? 'checked' : ''}`} aria-label={`${t.done ? 'Вернуть' : 'Выполнить'}: ${t.title}`} onClick={() => update(d => ({ ...d, tasks: d.tasks.map(x => x.id === t.id ? { ...x, done: !x.done } : x) }))}><Icon name="check" size={13} /></button><div><strong>{t.title}</strong><span>{data.clients.find(c => c.id === t.clientId)?.name || 'Команда'}</span></div><span className="task-time">{t.time}</span></div>)}</div><div className="modal-actions"><Button icon="plus" onClick={() => setModal({ type: 'task' })}>Добавить задачу</Button></div></Modal>;
  if (modal.type === 'person' || modal.type === 'report') { const p = modal.person || team[0]; return <Modal title={p.name} eyebrow="КАРТА НАВЫКОВ · УЧЕБНЫЙ ПРИМЕР" onClose={onClose}><div className="modal-person"><Avatar person={p} size="large" /><div><h3>{p.score} / 100</h3><span>Качество диалогов · {p.role}</span></div></div>{['Понимание задачи', 'Уточняющие вопросы', 'Работа с возражениями', 'Следующий шаг'].map((s, i) => <div className="competency" key={s}><div><span>{s}</span><strong>{p.skills[i]}</strong></div><div className="progress-track"><span style={{ width: `${p.skills[i]}%` }} /></div></div>)}<div className="report-observation"><h3>Сильная сторона</h3><p>Сохраняет спокойный тон и помогает клиенту сформулировать задачу.</p><h3>Следующий навык</h3><p>Уточнять причину возражения до того, как предлагать скидку. Практика: два диалога с сомневающимся клиентом.</p></div><p className="small-note">Это демонстрационная сводка навыков. В рабочей версии каждый вывод должен иметь цитаты и проверку наставника.</p><div className="modal-actions"><Button icon="book" onClick={() => { onClose(); go('academy'); }}>Открыть обучение</Button></div></Modal>; }
  if (modal.type === 'integration') { const details = { telegram: ['Telegram', 'Четыре тестовых аккаунта для проверки входящих сообщений, ответов, распределения диалогов и восстановления соединения.', 'Способ доступа к перепискам выбирается при интеграции. Наличие аккаунта само по себе не подключает его к CRM.'], max: ['MAX', 'Четыре тестовых аккаунта для проверки сценариев общения и импорта доступной истории.', 'Возможность доступа к личным перепискам зависит от разрешённых интерфейсов MAX. Перед разработкой интеграции нужно проверить конкретный способ подключения.'], gpt: ['OpenAI GPT', 'Массовые задачи направляются в экономичную модель. Сложные разборы и спорные ответы — в более сильную. В каждом случае передаётся выбранный контекст.', 'API-ключ хранится на сервере. Этот публичный макет не принимает ключи и не делает запросы к OpenAI.'], supabase: ['Supabase', 'Общая база хранит клиентов, сообщения, права доступа, учебные материалы и прогресс. Поиск выбирает относящиеся к вопросу фрагменты.', 'В рабочей версии потребуются серверная проверка доступа и резервное копирование. Сейчас данные хранятся в localStorage этого браузера.'] }[modal.id]; return <Modal title={details[0]} eyebrow="ПЛАН ИНТЕГРАЦИИ" onClose={onClose}><Badge tone="sand">Не подключено</Badge><div className="article-body"><p>{details[1]}</p><p>{details[2]}</p></div><div className="source-box"><Icon name="plug" size={22} /><p>Этот экран объясняет будущую функцию. Подключение сервиса в макете не выполняется.</p></div></Modal>; }
  if (modal.type === 'settings') return <Modal title="Настройки демонстрации" eyebrow="ВАШЕ РАБОЧЕЕ ПРОСТРАНСТВО" onClose={onClose}><div className="settings-option"><div><strong>Экспорт демоданных</strong><p>Скачать клиентов, задачи и прогресс в JSON.</p></div><Button variant="secondary" icon="download" onClick={exportData}>Скачать</Button></div><div className="settings-option"><div><strong>Начать демонстрацию заново</strong><p>Вернуть учебные данные и исходный прогресс.</p></div><Button variant="secondary" icon="refresh" onClick={() => setModal({ type: 'reset' })}>Сбросить</Button></div><p className="small-note">Не добавляйте в публичный макет реальные персональные данные. Серверное хранение и авторизация не подключены.</p></Modal>;
  if (modal.type === 'reset') return <Modal title="Начать заново?" eyebrow="СБРОС ДЕМО" onClose={onClose}><p className="modal-copy">Созданные в этом браузере демоклиенты, сообщения, задания и учебный прогресс будут заменены исходным примером. Перед сбросом можно скачать экспорт.</p><div className="modal-actions"><Button variant="secondary" onClick={exportData}>Скачать экспорт</Button><Button onClick={() => { update(() => newState()); onClose(); notify('Демонстрация начата заново'); go('overview'); }}>Сбросить демоданные</Button></div></Modal>;
  return <Modal title="Рабочее пространство, которое можно попробовать" eyebrow="ROYAL REACH · ИНТЕРАКТИВНЫЙ МАКЕТ" onClose={onClose} wide><div className="about-hero"><span className="icon-tile"><Icon name="growth" size={32} /></span><p>От переписки с клиентом — к понятному следующему шагу.<br />От рабочей ошибки — к новому навыку.</p></div><div className="about-grid"><div><h3>Уже работает в макете</h3><ul className="check-list"><li>Поиск, фильтры и карточки клиентов</li><li>Сохранение учебных сообщений и задач</li><li>Урок, тест и ролевая практика</li><li>Открытие следующих блоков и начисление XP</li><li>Утверждение примеров и поиск в базе знаний</li></ul></div><div><h3>Подключается в рабочей версии</h3><ul className="future-list"><li>Настоящие переписки Telegram и MAX</li><li>Генерация и анализ через GPT API</li><li>Supabase, авторизация и права доступа</li><li>Командная синхронизация и уведомления</li></ul></div></div><div className="about-notice"><Icon name="shield" size={19} /><p>Все люди и переписки вымышлены. ИИ-функции показывают готовые учебные сценарии. Изменения хранятся только в этом браузере.</p></div><div className="modal-actions"><Button icon="arrow" onClick={() => { onClose(); openChat('alex'); }}>Попробовать путь клиента</Button></div></Modal>;
}

function Lesson({ modal, onClose, data, update, notify }) {
  const [step, setStep] = useState(0); const [choice, setChoice] = useState(null); const [answer, setAnswer] = useState(''); const [evaluation, setEvaluation] = useState(null); const [finished, setFinished] = useState(false); const [awarded, setAwarded] = useState(0);
  const id = modal.moduleId; const module = modules[id]; const lesson = lessons[id];
  const titles = [lesson.title, 'Выберите следующий шаг', 'Попробуйте своими словами', 'Навык стал чуть сильнее'];
  function finish() { if (finished) return; const reward = modal.daily ? (data.dailyDone ? 0 : 40) : (data.completed.includes(id) ? 0 : 60); setAwarded(reward); setFinished(true); update(d => ({ ...d, completed: modal.daily ? d.completed : [...new Set([...d.completed, id])], xp: d.xp + reward, dailyDone: modal.daily ? true : d.dailyDone, streak: modal.daily && !d.dailyDone ? d.streak + 1 : d.streak, activity: [...d.activity, { type: 'lesson', moduleId: id, at: new Date().toISOString() }] })); setStep(3); }
  return <Modal title={titles[step]} eyebrow={`${modal.daily ? 'ЕЖЕДНЕВНАЯ ПРАКТИКА' : `БЛОК ${id + 1} · ${module.title.toUpperCase()}`} · ${Math.min(step + 1, 3)} / 3`} onClose={onClose} wide><div className="lesson-progress">{[0, 1, 2].map(n => <span key={n} className={step >= n ? 'active' : ''} />)}</div>{step === 0 && <div className="lesson-content"><div className="lesson-art"><Icon name="chat" size={45} /><span>{lesson.motto}</span></div><p className="lesson-lead">{lesson.lead}</p><div className="lesson-comparison"><div><span>Слишком рано</span><p>{lesson.bad}</p></div><div><span><Icon name="check" size={14} />Лучше начать так</span><p>{lesson.good}</p></div></div><div className="source-inline"><Icon name="file" size={15} />Учебный стандарт: «{lesson.source}»</div><div className="modal-actions"><Button onClick={() => setStep(1)}>Понятно, дальше <Icon name="arrow" size={16} /></Button></div></div>}{step === 1 && <div className="lesson-content"><div className="quiz-context"><Avatar person={data.clients[0]} /><div><strong>Алексей · учебный клиент</strong><p>«{lesson.quote}»</p></div></div><h3 className="quiz-title">Какой ответ помогает продолжить разговор?</h3><div className="quiz-options">{lesson.options.map((a, i) => <button key={a} className={`${choice === i ? 'selected' : ''} ${choice === i && i === 1 ? 'correct' : choice === i ? 'incorrect' : ''}`} onClick={() => setChoice(i)}><span>{String.fromCharCode(65 + i)}</span>{a}{choice === i && i === 1 && <Icon name="check" size={18} />}</button>)}</div>{choice !== null && <div role="status" className={`quiz-feedback ${choice === 1 ? 'success' : 'retry'}`}><strong>{choice === 1 ? 'Да, это помогает клиенту.' : 'Попробуйте ещё раз.'}</strong><p>{choice === 1 ? lesson.why : 'Ответ должен раскрыть состав предложения и помочь понять задачу. Давление и скидка пока не решают вопрос.'}</p></div>}<div className="modal-actions"><Button variant="ghost" onClick={() => setStep(0)}>Назад</Button><Button disabled={choice !== 1} onClick={() => setStep(2)}>К практике <Icon name="arrow" size={16} /></Button></div></div>}{step === 2 && <div className="lesson-content"><div className="roleplay-label"><Badge tone="green">Ролевой диалог</Badge><span>Учебный сценарий · локальная проверка</span></div><div className="roleplay-client"><Avatar person={data.clients[0]} /><div><strong>Алексей</strong><p>{lesson.practice}</p></div></div><label className="form-label">Ваш ответ<textarea rows={5} placeholder="Ответьте клиенту своими словами. Уточните задачу, задайте вопрос и предложите следующий шаг…" value={answer} onChange={e => { setAnswer(e.target.value); setEvaluation(null); }} maxLength={3000} /></label><div className="practice-meta"><span>Не меньше 30 символов</span><span>{answer.length} / 3 000</span></div>{evaluation && <div role="status" className="practice-evaluation"><h3>{evaluation.score === 3 && evaluation.valid ? 'Есть всё, чтобы продолжить диалог' : 'Хорошее начало. Давайте усилим ответ.'}</h3>{evaluation.checks.map(c => <div key={c.label} className={c.pass ? 'pass' : 'miss'}><Icon name={c.pass ? 'check' : 'plus'} size={16} />{c.label}<small>{c.pass ? 'Есть' : 'Добавьте'}</small></div>)}<p>{evaluation.score === 3 ? 'Вы уточнили задачу, задали вопрос и предложили действие. В рабочей версии качество формулировок дополнительно проверяет ИИ и наставник.' : 'Уточните ожидаемый результат, задайте клиенту вопрос и предложите конкретный следующий шаг.'}</p></div>}<p className="small-note">В этом макете проверяются учебные признаки ответа. Это демонстрация процесса, а не полноценная оценка ИИ.</p><div className="modal-actions"><Button variant="ghost" onClick={() => setStep(1)}>Назад</Button>{evaluation?.score === 3 && evaluation.valid ? <Button icon="check" onClick={finish}>Завершить практику</Button> : <Button icon="spark" disabled={answer.trim().length < 30} onClick={() => setEvaluation(evaluateAnswer(answer))}>Проверить ответ</Button>}</div></div>}{step === 3 && <div className="lesson-success"><div className="success-seal"><Icon name="check" size={38} /><span>✦</span></div><Badge tone="green">Практика завершена</Badge><h2 style={{whiteSpace: 'pre-line'}}>{lesson.success}</h2><p>{modal.daily ? 'Занятие на сегодня пройдено. Вернитесь завтра, чтобы закрепить навык.' : id < 3 ? `Блок «${module.title}» пройден. Следующий блок теперь доступен.` : 'Все базовые блоки пройдены. Продолжайте ежедневную практику.'}</p><div className="success-xp">✦ {awarded} XP <span>за освоенный навык*</span></div><small>*Баллы начисляются один раз за блок или первое ежедневное занятие в демо.</small><Button onClick={() => { onClose(); notify('Прогресс сохранён в этом браузере'); }}>Вернуться к маршруту <Icon name="arrow" size={17} /></Button></div>}</Modal>;
}

function Review({ client, onClose, data, update, notify, go }) {
  const [note, setNote] = useState(`Сначала ответьте на конкретный вопрос клиента, затем уточните ожидаемый результат и согласуйте следующий шаг.`); const [approved, setApproved] = useState(data.reviews.some(r => r.clientId === client.id));
  function approve() { if (approved) return; const id = 'case-' + client.id; update(d => ({ ...d, reviews: [...d.reviews, { id, clientId: client.id, note, at: new Date().toISOString() }], knowledge: [...d.knowledge, { id, title: `Практика: ${client.company}`, category: 'Из переписок', icon: 'chat', body: `Вопрос клиента: «${client.messages.filter(m => m.from === 'client').at(-1)?.text}»\n\nУчебный вывод: ${note}`, source: `Учебная переписка · ${client.name}. Утверждено в деморежиме наставника.`, updated: 'Сегодня', approved: true }] })); setApproved(true); notify('Пример утверждён и добавлен в базу знаний'); }
  return <Modal title="Из диалога — в полезный навык" eyebrow="ПРОВЕРКА НАСТАВНИКОМ · ДЕМОРЕЖИМ" onClose={onClose} wide><div className="review-client"><Avatar person={client} /><div><strong>{client.name}</strong><span>{client.company} · {client.channel}</span></div><Badge tone={approved ? 'green' : 'sand'}>{approved ? 'Утверждено' : 'На проверке'}</Badge></div><div className="review-content-grid"><div><span className="eyebrow">ЦИТАТА И КОНТЕКСТ</span><blockquote className="review-quote">«{client.messages.filter(m => m.from === 'client').at(-1)?.text}»</blockquote><h4>Факт</h4><p>Клиент задаёт вопрос. По этой реплике нельзя заключить, что он отказался от предложения.</p><h4>Критерий оценки</h4><p>Ответить по существу, выяснить задачу и договориться о следующем действии.</p></div><div><AIFlag>Предложенный учебный вывод</AIFlag><label className="form-label">Проверьте и отредактируйте<textarea rows={7} value={note} disabled={approved} maxLength={2000} onChange={e => setNote(e.target.value)} /></label><p className="small-note">В рабочей версии вывод предлагает GPT. В демо показан готовый пример; переключатель роли не даёт реальных прав доступа.</p></div></div><div className="modal-actions">{approved ? <><Button variant="secondary" onClick={() => { onClose(); go('knowledge'); }}>Открыть базу знаний</Button><Button icon="book" onClick={() => { onClose(); go('academy'); }}>Перейти к обучению</Button></> : <><Button variant="ghost" onClick={onClose}>Вернуться без утверждения</Button><Button icon="check" disabled={note.trim().length < 20} onClick={approve}>Утвердить для обучения</Button></>}</div></Modal>;
}

function NewClient({ onClose, update, notify }) { function submit(e) { e.preventDefault(); const form = new FormData(e.currentTarget); const name = form.get('name').trim(); const company = form.get('company').trim(); if (!name || !company) return; const client = { id: 'custom-' + Date.now(), name, company, initials: name.split(/\s+/).slice(0, 2).map(s => s[0]).join(''), color: 'sage', channel: form.get('channel'), stage: 0, amount: Number(form.get('amount')) || 0, unread: false, last: 'Новый учебный контакт', time: 'Сейчас', owner: 1, need: form.get('need').trim() || 'Задача ещё не уточнена', interest: 'Уточняется', messages: [] }; update(d => ({ ...d, clients: [...d.clients, client] })); onClose(); notify('Демоклиент добавлен'); } return <Modal title="Новый клиент" eyebrow="УЧЕБНАЯ КАРТОЧКА" onClose={onClose}><form onSubmit={submit}><label className="form-label">Имя и фамилия<input required name="name" maxLength={80} placeholder="Например, Иван Петров" /></label><label className="form-label">Компания<input required name="company" maxLength={100} placeholder="Название компании" /></label><div className="form-columns"><label className="form-label">Канал<select name="channel"><option>Telegram</option><option>MAX</option></select></label><label className="form-label">Сумма, ₽<input name="amount" type="number" min="0" max="100000000" defaultValue="0" /></label></div><label className="form-label">Задача клиента<textarea name="need" rows={3} maxLength={600} placeholder="Какую задачу хочет решить клиент?" /></label><p className="small-note">Используйте вымышленные данные. Внешние сервисы не подключены.</p><div className="modal-actions"><Button type="submit" icon="plus">Добавить клиента</Button></div></form></Modal>; }
function NewTask({ client, onClose, update, notify }) { function submit(e) { e.preventDefault(); const f = new FormData(e.currentTarget); const title = f.get('title').trim(); if (!title) return; update(d => ({ ...d, tasks: [...d.tasks, { id: Date.now(), title, clientId: client?.id || null, time: f.get('time'), done: false }] })); onClose(); notify('Задача добавлена в план на день'); } return <Modal title="Следующий шаг" eyebrow={client?.name?.toUpperCase() || 'ПЛАН НА ДЕНЬ'} onClose={onClose}><form onSubmit={submit}><label className="form-label">Что нужно сделать<input required name="title" maxLength={200} placeholder="Например, прислать два варианта предложения" /></label><label className="form-label">Сегодня, к какому времени<input required type="time" name="time" defaultValue="16:00" /></label><div className="modal-actions"><Button type="submit" icon="check">Сохранить задачу</Button></div></form></Modal>; }
function NewKnowledge({ onClose, update, notify }) { function submit(e) { e.preventDefault(); const f = new FormData(e.currentTarget); const title = f.get('title').trim(); const body = f.get('body').trim(); if (!title || body.length < 20) return; update(d => ({ ...d, knowledge: [...d.knowledge, { id: 'note-' + Date.now(), title, body, category: f.get('category'), icon: 'file', source: 'Учебный материал · добавлен в деморежиме наставника', updated: 'Сегодня', approved: true }] })); onClose(); notify('Учебный материал добавлен'); } return <Modal title="Добавить знание команды" eyebrow="ДЕМОРЕЖИМ НАСТАВНИКА" onClose={onClose}><form onSubmit={submit}><label className="form-label">Название<input name="title" required maxLength={140} /></label><label className="form-label">Категория<select name="category">{['Методология', 'Продукт', 'Возражения', 'Коммуникация'].map(c => <option key={c}>{c}</option>)}</select></label><label className="form-label">Материал<textarea name="body" required minLength={20} maxLength={10000} rows={7} placeholder="Опишите правило и приведите пример…" /></label><p className="small-note">Добавление показывает процесс утверждения. Реальные права наставника появятся после подключения авторизации.</p><div className="modal-actions"><Button type="submit" icon="check">Утвердить и сохранить</Button></div></form></Modal>; }
function AskKnowledge({ data, onClose, setModal }) { const [query, setQuery] = useState(''); const [asked, setAsked] = useState(false); const matches = searchKnowledge(data.knowledge, query); return <Modal title="Спросить базу знаний" eyebrow="ПОИСК С УКАЗАНИЕМ ИСТОЧНИКА" onClose={onClose} wide><form className="ask-form" onSubmit={e => { e.preventDefault(); setAsked(true); }}><input aria-label="Вопрос базе знаний" value={query} required minLength={3} onChange={e => { setQuery(e.target.value); setAsked(false); }} placeholder="Например: как отвечать на возражение о цене?" /><Button type="submit" icon="search">Найти</Button></form><div className="example-queries">{['Как отвечать на дорого?', 'Следующий шаг', 'Результат кампании'].map(s => <button key={s} onClick={() => { setQuery(s); setAsked(true); }}>{s}</button>)}</div>{asked && <div className="knowledge-answer">{matches.length ? <><Badge tone="green">Найдено в утверждённых материалах</Badge>{matches.slice(0, 3).map(m => <div className="search-result" key={m.id}><h3>{m.title}</h3><p>{m.body}</p><button onClick={() => setModal({ type: 'article', article: m })}><Icon name="file" size={14} />{m.source}<Icon name="arrow" size={14} /></button></div>)}</> : <Empty title="В базе нет подходящего материала" text="Попробуйте другие слова. В демо нет генерации ответа при отсутствии источника." />}</div>}<p className="small-note">Локальный поиск по словам. После интеграции GPT сможет составлять ответ из выбранных фрагментов.</p></Modal>; }
function GlobalSearch({ data, onClose, openChat, setModal, go }) { const [q, setQ] = useState(''); const clients = data.clients.filter(c => (c.name + ' ' + c.company).toLowerCase().includes(q.toLowerCase())); const docs = data.knowledge.filter(k => k.title.toLowerCase().includes(q.toLowerCase())); return <Modal title="Найти в рабочем пространстве" eyebrow="КЛИЕНТЫ · ЗНАНИЯ · РАЗДЕЛЫ" onClose={onClose}><label className="input-search global-search-input"><Icon name="search" size={19} /><input autoFocus aria-label="Поиск по рабочему пространству" placeholder="Введите имя, компанию или тему" value={q} onChange={e => setQ(e.target.value)} /></label><div className="global-results">{q ? <><span className="eyebrow">КЛИЕНТЫ</span>{clients.map(c => <button key={c.id} onClick={() => { onClose(); openChat(c.id); }}><Avatar person={c} size="small" /><span>{c.name}<small>{c.company}</small></span><Icon name="arrow" size={16} /></button>)}<span className="eyebrow">БАЗА ЗНАНИЙ</span>{docs.map(k => <button key={k.id} onClick={() => setModal({ type: 'article', article: k })}><Icon name="file" size={18} /><span>{k.title}</span><Icon name="arrow" size={16} /></button>)}{!clients.length && !docs.length && <Empty />}</> : nav.slice(0, 6).map(n => <button key={n.id} onClick={() => { onClose(); go(n.id); }}><Icon name={n.icon} size={18} /><span>{n.name}</span><Icon name="arrow" size={16} /></button>)}</div></Modal>; }

class ErrorBoundary extends React.Component { constructor(props) { super(props); this.state = { error: false }; } static getDerivedStateFromError() { return { error: true }; } render() { if (this.state.error) return <div className="app-error"><h1>Давайте начнём с чистого листа</h1><p>Не удалось открыть сохранённое состояние макета. Можно скачать данные и сбросить демо.</p><button onClick={() => { const raw = localStorage.getItem(STORAGE_KEY) || '{}'; const url = URL.createObjectURL(new Blob([raw], { type: 'application/json' })); const a = document.createElement('a'); a.href = url; a.download = 'royal-reach-recovery.json'; a.click(); URL.revokeObjectURL(url); }}>Скачать сохранённые данные</button><button onClick={() => { localStorage.removeItem(STORAGE_KEY); location.hash = 'overview'; location.reload(); }}>Сбросить демо</button></div>; return this.props.children; } }
createRoot(document.getElementById('root')).render(<ErrorBoundary><App /></ErrorBoundary>);
